package main

import (
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
)

func main() {
	data, _ := io.ReadAll(os.Stdin)
	fields := strings.Fields(string(data))
	max, first := 0, true
	for _, f := range fields {
		n, err := strconv.Atoi(f)
		if err != nil {
			continue
		}
		if first || n > max {
			max = n
			first = false
		}
	}
	fmt.Printf("max=%d\n", max)
}

package main

import (
	"fmt"
	"io"
	"os"
	"strings"
)

func main() {
	data, _ := io.ReadAll(os.Stdin)
	parts := strings.Split(string(data), ",")
	c := 0
	for _, w := range parts {
		if strings.TrimSpace(w) != "" {
			c++
		}
	}
	fmt.Printf("words=%d\n", c)
}

package main

import (
	"fmt"
	"io"
	"os"
	"strings"
)

func main() {
	data, _ := io.ReadAll(os.Stdin)
	s := string(data)
	lines := strings.Count(s, "\n")
	fmt.Printf("lines=%d chars=%d\n", lines, len(s))
}

